const list = document.querySelector('#list')
const remove = document.querySelector('.remove')
if (remove) {
  remove.addEventListener('click', event => event.target.closest('li').remove())
}
document.querySelector('#add').addEventListener('click', () => {
  const item = document.createElement('li')
  item.innerHTML = '<span>新的待办</span> <button class="remove" type="button">删除</button>'
  list.append(item)
})

const buttons = document.querySelectorAll('.tab')
for (var i = 0; i < buttons.length; i++) {
  buttons[i].addEventListener('click', () => console.log('点击了第', i, '个标签'))
}

const add = document.querySelector('#add')
function addItem() { document.querySelector('#list').append('新条目') }
add.addEventListener('click', addItem)
add.addEventListener('click', addItem)

const input = document.querySelector('#q')
input.addEventListener('keydown', event => {
  if (event.keyCode === 13) { document.querySelector('#hint').textContent = '开始搜索' }
})

const out = document.querySelector('#out')
async function load(tab) {
  const data = await fetch('/api/tab/' + tab).then(response => response.json())
  out.replaceChildren(...data.map(item => Object.assign(document.createElement('li'), { textContent: item })))
}
document.querySelectorAll('.tab').forEach(button => {
  button.addEventListener('click', () => load(button.dataset.tab))
})
